+use crate::api::client::ApiClient;
+use crate::models::{ResultWithDefaultError, TimeEntry};
+use crate::utilities;
+use chrono::{Datelike, NaiveDate};
+use std::collections::BTreeMap;
+
+/// Apply the invoice billing rule to one stopped entry. Billing is rounded up
+/// per entry to the next quarter hour, so separate entries are never merged
+/// before rounding.
+pub fn billable_seconds(entry: &TimeEntry) -> i64 {
+    if !entry.billable || entry.is_running() || entry.duration <= 0 {
+        return 0;
+    }
+    ((entry.duration + 899) / 900) * 900
+}
+
+fn week_monday(entry: &TimeEntry) -> NaiveDate {
+    let date = entry.start.date_naive();
+    date - chrono::Duration::days(date.weekday().num_days_from_monday() as i64)
+}
+
+pub fn weekly_totals(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
+    let mut totals = BTreeMap::new();
+    for entry in entries {
+        let seconds = billable_seconds(entry);
+        if seconds != 0 {
+            *totals.entry(week_monday(entry)).or_insert(0) += seconds;
+        }
+    }
+    totals
+}
+
+pub struct BillWeeklyCommand;
+
+impl BillWeeklyCommand {
+    pub async fn execute(
+        api_client: impl ApiClient,
+        since: Option<String>,
+        until: Option<String>,
+    ) -> ResultWithDefaultError<()> {
+        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
+        let entries = api_client
+            .get_time_entries_filtered_minimal(since, until)
+            .await?;
+        let totals = weekly_totals(&entries);
+
+        if totals.is_empty() {
+            println!("(no data)");
+            return Ok(());
+        }
+
+        let total: i64 = totals.values().sum();
+        for (week, seconds) in totals {
+            println!("{}  {}s", week.format("%Y-%m-%d"), seconds);
+        }
+        println!("Total  {total}s");
+        Ok(())
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use chrono::{TimeZone, Utc};
+
+    fn entry(start: i64, duration: i64, billable: bool, running: bool) -> TimeEntry {
+        TimeEntry {
+            start: Utc.timestamp_opt(start, 0).single().unwrap(),
+            duration: if running { -start } else { duration },
+            billable,
+            ..Default::default()
+        }
+    }
+
+    #[test]
+    fn rounds_each_billable_stopped_entry_up_to_quarter_hour() {
+        assert_eq!(billable_seconds(&entry(0, 901, true, false)), 1800);
+        assert_eq!(billable_seconds(&entry(0, 900, true, false)), 900);
+        assert_eq!(billable_seconds(&entry(0, 1, false, false)), 0);
+        assert_eq!(billable_seconds(&entry(0, 901, true, true)), 0);
+    }
+
+    #[test]
+    fn groups_by_utc_iso_week_and_sorts_oldest_first() {
+        let entries = vec![
+            entry(chrono::DateTime::parse_from_rfc3339("2026-03-08T23:00:00Z").unwrap().timestamp(), 1, true, false),
+            entry(chrono::DateTime::parse_from_rfc3339("2026-03-02T00:00:00Z").unwrap().timestamp(), 900, true, false),
+        ];
+        let totals = weekly_totals(&entries);
+        assert_eq!(totals.keys().next().unwrap().to_string(), "2026-03-02");
+        assert_eq!(totals[&NaiveDate::from_ymd_opt(2026, 3, 2).unwrap()], 1800);
+        assert_eq!(totals[&NaiveDate::from_ymd_opt(2026, 3, 9).unwrap()], 900);
+    }
+}
